import json,pathlib
b={'start':1710,'end':1790,'decisions':{}}
def c(i,t,r):b['decisions'][str(i)]={'decision':'change','target':t,'reason':r}
c(1710,'<ffx:fear_light>صبرًا أيها الإخوة والأخوات!<ffx:smile> الصبر والتسامح؛ تقبلوا جيرانكم كما<ffx:smile_light> يقبلكم الرب،<ffx:wonder> كي تردوا قلوبهم عن الخطيئة إلى<ffx:smile> النعيم السماوي للإيمان الحق!','تصحيح مخاطب الجمع والغاية من تقبل الجيران والربط النحوي.')
c(1711,'<ffx:wonder>فلنغفر للطفلة،<ffx:smile_light> فهي لا تدرك حماقة أقوالها...<ffx:smile> فلنغفر أيها الإخوة...<ffx:sadness> ولنصل من أجل أرواح الخطاة...<ffx:smile> ولنغفر للطفلة كما<ffx:wonder_strong> يغفر لنا الرب! آمين!<ffx:wonder_light>','صقل نبرة الوعظ واستعادة موضع وسم ختام الدعاء.')
c(1712,'<ffx:wonder_strong>الرب رحيم، فهو<ffx:smile_light> يغفر لمن يرفضون<ffx:disgust> حماقة الكهرباء وإغواءها، وسائر إغراءات العدو الآثمة!<ffx:smile> ويمنح الخلاص لمن يتعثرون،<ffx:wonder> كما منحه لنا...','absolves يغفر الذنوب لا تبرئة قانونية، وإصلاح إسناد حماقة الكهرباء.')
c(1713,'<ffx:wonder>ويغفر لنا خطايانا، ما نعلم منها وما لا نعلم، ليتحد جميع أبنائه<ffx:wonder_strong> في الإيمان الحق وينالوا الخلاص!<ffx:smile> لذلك تظل أحضاننا مفتوحة لإخوة جدد، وستبقى كذلك إلى أبد الآبدين!<ffx:wonder_light>','absolves مغفرة لا تبرير أفعال، وصياغة الانضمام إلى الجماعة.')
c(1714,'<ffx:smile>فتعالوا، وانبذوا الحماقة والخطيئة،<ffx:wonder_strong> وانعموا بالخلاص في ديرنا! آمين!<ffx:wonder_light>','embrace salvation قبول الخلاص والانضمام إليه لا احتضان مادي.')
for i in range(1720,1725):c(i,'<ffx:wonder_strong>اقبل الخلاص!<ffx:wonder_light>','صيغة دعوة واضحة للخلاص بدل احتضانه حرفيًا.')
c(1730,'اللعنة، الباقون خارج نطاق نيراني! احذر!','إصلاح الأمر الناقص احرص ومعنى خط نيران القناصة.')
c(1731,'أعيد التلقيم!','إعلان المتحدثة إعادة التلقيم لا مصدر مجرد.')
c(1732,'انتظر، أعيد التلقيم!','توحيد إعادة التلقيم بدل التحميل وإصلاح فاعلها.')
c(1733,'أرتيوم، لا أستطيع تغطيتك وأنت في الداخل. سأغير موقعي لألتقي بالمرأة والطفلة. أعرف أنك ستتدبر أمرك جيدًا!','position موقع القنص لا موقف رأي، والطفلة ناستيا لا صبي.')
c(1734,'أحسنت يا أرتيوم. وكأنك نينجا حقيقي...','ثناء طبيعي على التسلل وحفظ تشبيه النينجا.')
c(1736,'رائع! بدأت أقلق، فقد أحدثت فوضى عارمة هناك!','raised hell إحداث فوضى الاشتباك لا إثارة جحيم حرفي.')
c(1737,'أود تقبيلك الآن! لكن علي إيصال كاتيا وناستيا إلى أورورا، فأراك هناك! تفقد الخريطة... يبدو أنك تستطيع التجديف إليها مباشرة من موقعك.','تصحيح مخاطب المفرد وإكمال وجهة التجديف وحفظ ترتيب مهام آنا.')
c(1738,'من المؤسف أنك لم تستطع الإفلات بهدوء، دون سفك دماء... سيزداد كرههم لنا حتمًا الآن...','حفظ فرع سفك الدماء الماضي لا عجز عام دائم، وبنبرة أسف لا عار شخصي.')
c(1739,'حسنًا... يا أرتيوم، كاتيا وناستيا معي الآن، فأراك على أورورا. تفقد الخريطة... يبدو أنك تستطيع التجديف إليها مباشرة من هناك...','أرتيوم منادى وليس واحدًا ممن التقتهم آنا؛ تصحيح هذا اللبس النحوي المؤثر.')
c(1743,'<ffx:smile>لا أصدق هذا... لقد كدت<ffx:sadness> أفقد الأمل!','all but lost كادت تفقد الأمل لا كان لديها كل ثم فقدته.')
c(1746,'يبدو أننا وجدنا مصدر معلوماتنا...','informer كاتيا مصدر المعلومات المطلوبة لا مخبر مذكر بالضرورة.')
c(1748,'<ffx:fear>آه! إنهم حرس الجسر!...<ffx:disgust_light> خدعهم سيلانتيوس كالسكان المحليين،<ffx:fear> لكن حرس الجسر، بخلافهم، يحملون بنادق...','Bridge Guard فرقة حرس جمع لا حارس واحد؛ حفظ اختلاف تسليحهم عن المحليين.')
c(1749,'اركض! هناك مخرج هنا في الأسفل، وقارب عند الرصيف...','Run فعل أمر لا يجري، واستعادة اتجاه الخروج إلى الأسفل.')
c(1750,'<ffx:wonder>لدينا قارب أيضًا، لكنه<ffx:sadness> أصغر من أن يحملنا جميعًا...<ffx:neutral>','قارب مذكر ومرجع one صريح لا واحدة.')
c(1752,'<ffx:fear>انطلق! أنا وناستيا<ffx:wonder> نستطيع الوصول إلى قطارك وحدنا...<ffx:wonder_light>','إصلاح فصل الواو وصياغة طمأنة كاتيا بشأن وصولها وطفلتها.')
c(1754,'<ffx:wonder>وأحضر العم كريست من الميناء!<ffx:smile> إنه بارع، يستطيع إصلاح أي شيء!<ffx:neutral>','get إحضار المهندس لا إخراجه من ميناء محتجز فيه.')
c(1755,'أرتيوم، سألتقي بهما وأوصلهما سالمتين إلى أورورا، فلا تقلق... اذهب إلى الرصيف، أرى القارب هناك.','تصحيح إحالة آنا إلى المرأة والطفلة المثنى المؤنث.')
c(1756,'<ffx:fear_light>أرجوك، اركض...<ffx:fear> سيطعمونك للسمكة إن أمسكوا بك...<ffx:sadness_light>','Fish السمكة المحددة المفردة في عبادة الطائفة لا أسماك عامة.')
c(1757,'<ffx:sadness_strong>أولئك الحمقى المتخلفون، تبًا لهم!<ffx:sadness_light>','backwards تخلف فكري لا حركة إلى الوراء، وحفظ الشتيمة.')
c(1758,'<ffx:fear_strong>آآه! إنها خطيئة، خطيئة! أطفئه!<ffx:fear_light>','المطلوب إطفاؤه المصباح المذكر لا الخطيئة نفسها.')
c(1761,'<ffx:fear_strong>أطفئ ضوء الشيطان! أطفئه!<ffx:fear_light>','Off تكرار أمر الإطفاء لا حرف الجر عن.')
c(1768,'أرتيوم، قارب يقترب متسترًا بالضباب!','استعادة التنكير للقارب الذي وصل حديثًا ومعنى غطاء الضباب.')
c(1771,'<ffx:anger>ماذا تريدون؟!','كاتيا تخاطب مجموعة حرس الجسر عند الباب.')
c(1773,'<ffx:wonder_strong>أي زنديق؟<ffx:wonder>','صياغة سؤال الإنكار الطبيعي.')
c(1774,'الذي استدعاه نسلك اللعين!','spawn النسل على سبيل الازدراء لا فعل تفرخك.')
c(1775,'<ffx:sadness_strong>الأب سيلانتيوس يحذرنا من الخرافات،<ffx:wonder> ولم أر أي زنديق.<ffx:anger> وحتى لو رأيت، فلن يهمني!<ffx:neutral>','إصلاح فعل رأيت المقدّر بدل فعلت الغامض وحفظ تحدي كاتيا.')
c(1776,'هذا ما سنتحقق منه! افتحي!','أمر لِكاتيا المؤنثة بفتح الباب.')
c(1777,'<ffx:fear_strong>ماذا؟! أنسيتم ما قاله الأب سيلانتيوس؟<ffx:disgust> قال إنه لا يجوز لرجل غيره أن يدخل هذه الغرفة!<ffx:fear_strong> سيعرف بما تفعلون!<ffx:anger_light>','تصحيح إن بعد القول وحفظ حظر دخول الرجال تحديدًا، وخطاب مجموعة الحراس.')
c(1778,'نفعل هذا بأمره... افتحي، تبًا!','تصحيح أمر فتح الباب الموجه إلى كاتيا.')
c(1779,'<ffx:wonder_strong>وهذا أمره أيضًا!<ffx:disgust> استدعوه إلى هنا وانتظروا!<ffx:neutral>','call over استدعاء حضوره إلى الباب لا مكالمة لاسلكية، وأمر للجمع.')
c(1780,'انتظري فحسب... الأب المقدس لن يتسامح مع هذا!','التهديد لِكاتيا المؤنثة وتوحيد لقب الأب المقدس.')
c(1782,'<ffx:sadness_light>اهدئي، اهدئي يا حبيبتي، اهدئي... صه... صه...<ffx:smile_light> أمك ستحميك...','pumpkin اسم تدليل لا يقطينة فعلية، وناستيا أنثى؛ الأم تطمئنها لا تأمرها بخشونة بالصمت.')
c(1783,'<ffx:wonder_strong>آه... أين كاتيا؟<ffx:wonder>','Umm صوت تردد لا كلمة أم ذات معنى مختلف.')
c(1785,'<ffx:wonder>هل وجدتم الزنديق أيها الإخوة؟<ffx:neutral>','توحيد heretic إلى زنديق بدل تنويع المصطلح إلى مهرطق.')
c(1787,'<ffx:wonder>هل وجدتموه؟ أم<ffx:anger> أبحث عنه بنفسي أيها الإخوة؟<ffx:neutral>','الجمع ثابت في نداء الإخوة وتصحيح أمر السؤال.')
c(1788,'<ffx:wonder>هل وجدتموه يا أبنائي؟<ffx:neutral>','أتباع الكاهن بالغون مخاطبون جمع، وmy children يا أبنائي لا أطفالي حرفيًا.')
(pathlib.Path(__file__).parent/'batch_1710.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
